{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Cloud SQL instance has no SSL enforced",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "The 'require_ssl' attribute is set to false, allowing unencrypted connections to the database which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_GCP_11",
      "title": "Cloud SQL automated backups are disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Automated backups are disabled ('enabled = false'), preventing point-in-time recovery and increasing the risk of permanent data loss."
    },
    {
      "check_id": "CKV_GCP_12",
      "title": "Cloud SQL deletion protection is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "LOW",
      "explanation": "Deletion protection is set to false, meaning the database can be accidentally deleted via Terraform destroy or console actions without safeguards."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = true\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"off\"\n    }\n  }\n}",
  "fix_summary": "Enabled SSL enforcement by setting 'require_ssl' to true. Enabled automated backups by setting 'backup_configuration.enabled' to true. Enabled deletion protection by setting 'deletion_protection' to true to prevent accidental destruction."
}
